What does the following C program print? (C99 or later; integer division truncates toward zero.)

```c
#include <stdio.h>
int main(void){ printf("%d %d %d", 7/2, -7/2, -7%3); return 0; }
```

What is printed?

```c
#include <stdio.h>
int main(void){ int x = 5; int *p = &x; *p = 9; printf("%d", x); return 0; }
```

What is printed?

```c
#include <stdio.h>
int main(void){ int a[] = {10,20,30,40}; printf("%d %d", a[2], *(a+1)); return 0; }
```

What does this print? (Assume sizeof(char) is 1, as always.)

```c
#include <stdio.h>
#include <string.h>
int main(void){ char s[] = "GATE"; printf("%d %d", (int)strlen(s), (int)sizeof(s)); return 0; }
```

What is printed?

```c
#include <stdio.h>
void f(void){ static int c = 0; c++; printf("%d ", c); }
int main(void){ f(); f(); f(); return 0; }
```

What is printed by this program?

```c
#include <stdio.h>
void f(int a){ a = a + 10; }
int main(void){ int v = 3; f(v); printf("%d", v); return 0; }
```

What is printed?

```c
#include <stdio.h>
void sw(int *a, int *b){ int t = *a; *a = *b; *b = t; }
int main(void){ int x = 4, y = 7; sw(&x, &y); printf("%d %d", x, y); return 0; }
```

What is printed?

```c
#include <stdio.h>
int main(void){ int m[2][3] = {{1,2,3},{4,5,6}}; printf("%d %d", m[1][0], ((int *)m)[4]); return 0; }
```

What is printed? (`&&` evaluates left to right and short-circuits.)

```c
#include <stdio.h>
int main(void){ int i = 0; if (i++ && i++) { } printf("%d", i); return 0; }
```

What is printed? (`&`, `|`, `^` are bitwise AND, OR, XOR.)

```c
#include <stdio.h>
int main(void){ printf("%d %d %d", 12&10, 12|10, 12^10); return 0; }
```

Which of the following describes the program below?

```c
#include <stdlib.h>
int main(void){ int *p = malloc(sizeof(int)); *p = 1; p = malloc(sizeof(int)); *p = 2; free(p); return 0; }
```

What is printed? (`p - q` on pointers into the same array gives the number of elements between them.)

```c
#include <stdio.h>
int main(void){ int a[] = {2,4,6,8,10}; int *p = a+1, *q = a+4; printf("%d %d %d", (int)(q-p), p[2], *(p-1) + *p); return 0; }
```

What is printed?

```c
#include <stdio.h>
int main(void){ char *s = "abcdef"; s += 2; printf("%s %c", s, *(s+1)); return 0; }
```

What is printed? (The three values are computed in separate statements.)

```c
#include <stdio.h>
int g = 10;
int f(void){ static int c = 0; int t = 0; c += 2; t += 2; g++; return c + t + g; }
int main(void){ int a = f(); int b = f(); printf("%d %d %d", a, b, g); return 0; }
```

What is printed?

```c
#include <stdio.h>
int x = 1;
int main(void){ { int x = 2; { x++; } printf("%d ", x); } printf("%d", x); return 0; }
```

What is printed?

```c
#include <stdio.h>
void setp(int **pp, int *q){ *pp = q; }
int main(void){ int a = 1, b = 2; int *p = &a; setp(&p, &b); *p = *p + 10; printf("%d %d", a, b); return 0; }
```

What is printed?

```c
#include <stdio.h>
int main(void){ int s = 0; for (int i = 1; i <= 10; i++) { if (i%2 == 0) continue; if (i > 7) break; s += i; } printf("%d", s); return 0; }
```

What is printed?

```c
#include <stdio.h>
int main(void){ unsigned int a = 3; int b = 5; if (a - b > 0) puts("pos"); else puts("nonpos"); return 0; }
```

What is printed?

```c
#include <stdio.h>
int main(void){ int m[3][4]; for (int i=0;i<3;i++) for (int j=0;j<4;j++) m[i][j] = i*4 + j;
  printf("%d %d", *(*(m+2)+1), ((int *)m)[6]); return 0; }
```

What is printed? (This is a hand-written `strcat`.)

```c
#include <stdio.h>
#include <string.h>
int main(void){ char a[20] = "gate"; char b[20] = "2027"; char *p = a, *q = b;
  while (*p) p++;
  while ((*p++ = *q++)) ;
  printf("%s %d", a, (int)strlen(a)); return 0; }
```

What is printed? (`n & (n-1)` clears the lowest set bit.)

```c
#include <stdio.h>
int f(int n){ int c = 0; while (n) { n = n & (n-1); c++; } return c; }
int main(void){ int s = 0; for (int i = 1; i <= 15; i++) s += f(i); printf("%d", s); return 0; }
```

What is printed?

```c
#include <stdio.h>
#include <string.h>
int main(void){ char *names[] = {"ab","cde","f"};
  printf("%c %s %d", *names[1], names[2], (int)strlen(*(names+1)+1)); return 0; }
```

What is printed?

```c
#include <stdio.h>
struct P { int x, y, z; };
int main(void){ struct P a[3] = {{1,2,3},{4,5,6},{7,8,9}}; struct P *q = a + 1;
  printf("%d %d", (q+1)->y, (*q).z + q[-1].x); return 0; }
```

Let `m` and `n` point to valid NULL-terminated singly linked lists (possibly empty, i.e. NULL), and consider

```c
struct node { int d; struct node *nx; };
void join(struct node *m, struct node *n){ struct node *p = n; while (p->nx) p = p->nx; p->nx = m; }
```

Which of the following are TRUE?

What is printed? (`*p++` parses as `*(p++)`; `(*p)++` increments the pointed-to value.)

```c
#include <stdio.h>
int main(void){ int a[] = {10,20,30,40}; int *p = a;
  int x = *p++; int y = (*p)++; int z = *++p;
  printf("%d %d %d %d %d", x, y, z, a[1], (int)(p-a)); return 0; }
```

What is printed? (assume an ordinary hosted C implementation)

```c
#include <stdio.h>
#include <string.h>
int main(void){ char s1[] = "abc\0def"; char *s2 = "abc\0def";
  printf("%d %d %d", (int)sizeof(s1), (int)strlen(s1), (int)strlen(s2)); return 0; }
```

What is the output of this program?

```c
#include <stdio.h>
int main(void){ int i = 5; int j = i++ + ++i; printf("%d", j); return 0; }
```

What is printed?

```c
#include <stdio.h>
int *f(void){ static int v = 0; v += 5; return &v; }
int main(void){ int *a = f(); int *b = f(); printf("%d %d", *a, *b); return 0; }
```

What is printed?

```c
#include <stdio.h>
int main(void){ int a[2][3] = {{1,2,3},{4,5,6}}; int (*p)[3] = a;
  printf("%d %d %d", (*p)[2], (*(p+1))[1], **(a+1)); return 0; }
```

What is printed? (Statements inside `f` are sequenced, so the result is well-defined.)

```c
#include <stdio.h>
int f(int n){ static int s = 0; if (n <= 0) return s; s += n; int a = f(n-1); int b = f(n-2); return a + b; }
int main(void){ printf("%d", f(4)); return 0; }
```

What is printed? (Recall the precedence order: `!` / unary, `+`, `<<`, relational, `==`, `&`.)

```c
#include <stdio.h>
int main(void){ int a = 5, b = 3; printf("%d %d %d", a & b == 3, a << 1 + 1, !a + b); return 0; }
```
